<?php
declare(strict_types=1);require __DIR__.'/bootstrap.php';$db=saas_db();$profileId=(int)($_SESSION['passenger_profile_id']??0);$accountId=(int)($_SESSION['passenger_account_id']??0);if(!$profileId||!$accountId)saas_redirect('passenger_auth.php');$ticketId=(int)($_GET['ticket_id']??0);if(!$ticketId){http_response_code(400);exit('Ticket is required.');}$q=$db->prepare("SELECT ti.id,ti.tour_passenger_id,ti.ticket_number,ti.template_key,ti.status,ti.issued_at,t.name tour_name,t.start_date,t.end_date,pp.full_name,pp.phone FROM ticket_instances ti JOIN tour_passengers tp ON tp.id=ti.tour_passenger_id JOIN passenger_profiles pp ON pp.id=tp.passenger_profile_id JOIN tours t ON t.id=tp.tour_id JOIN passenger_accounts pa ON pa.passenger_profile_id=pp.id WHERE ti.id=? AND pp.id=? AND pa.id=? AND ti.status='ISSUED' AND ti.voided_at IS NULL LIMIT 1");$q->execute([$ticketId,$profileId,$accountId]);$t=$q->fetch();if(!$t){http_response_code(404);exit('Ticket not found or no longer valid.');}$q=$db->prepare("SELECT s.seat_code,b.name,b.bus_number FROM passenger_seat_assignments psa JOIN seats s ON s.id=psa.seat_id JOIN buses b ON b.id=psa.bus_id WHERE psa.tour_passenger_id=? LIMIT 1");$q->execute([(int)$t['tour_passenger_id']]);$seat=$q->fetch()?:[];$qr=hash_hmac('sha256',(string)$t['ticket_number'],saas_app_key());$path=rtrim(dirname((string)($_SERVER['SCRIPT_NAME']??'/')),'/');$verify=$path.'/ticket_verify.php?ticket='.rawurlencode((string)$t['ticket_number']).'&q='.rawurlencode($qr);?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Ticket</title><style>body{font-family:Arial,sans-serif;background:#f4f7fb;margin:0;color:#172033}.wrap{max-width:700px;margin:35px auto;padding:16px}.ticket{background:#fff;border-radius:18px;padding:25px;box-shadow:0 8px 30px #0001;border:2px solid #172033}.muted{color:#667085;font-size:13px}.row{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:18px 0}.item{background:#f8fafc;padding:12px;border-radius:9px}.qr{margin-top:20px;text-align:center}.qr img{width:170px;height:170px}.btn{display:inline-block;padding:9px 13px;border-radius:8px;background:#155eef;color:#fff;text-decoration:none;margin-top:12px}@media(max-width:600px){.row{grid-template-columns:1fr}}</style></head><body><main class="wrap"><p><a href="passenger_dashboard.php">← My Tours</a></p><section class="ticket"><h1><?=saas_h($t['tour_name'])?></h1><p class="muted">Ticket <?=saas_h($t['ticket_number'])?> · <?=saas_h($t['status'])?></p><div class="row"><div class="item"><b>Passenger</b><br><?=saas_h($t['full_name'])?><br><?=saas_h($t['phone']??'')?></div><div class="item"><b>Date</b><br><?=saas_h((string)$t['start_date'])?><?=($t['end_date']?' → '.saas_h((string)$t['end_date']):'')?></div><?php if($seat):?><div class="item"><b>Bus</b><br><?=saas_h($seat['name'])?><?=($seat['bus_number']?' · '.saas_h($seat['bus_number']):'')?></div><div class="item"><b>Seat</b><br><?=saas_h($seat['seat_code'])?></div><?php endif;?></div><div class="qr"><img src="https://api.qrserver.com/v1/create-qr-code/?size=220x220&data=<?=rawurlencode($verify)?>" alt="Ticket QR"><div class="muted">Scan to verify this ticket</div><a class="btn" href="<?=saas_h($verify)?>">Verify ticket</a></div></section></main></body></html>